// Lo que manda el agente, mas de que instancia viene y a quien atiende.
// NUNCA recibe el company_id: se deriva adentro de la base. Si una
// herramienta aceptara la empresa del payload, bastaria un error del agente
// para tocarle los datos a otro cliente.
const b = $input.first().json.body || $input.first().json;

// Todo viaja como UN jsonb. El nodo de Postgres parte los parametros por
// coma, y por aqui pasan nombres de producto escritos por una persona.
const payload = Object.assign({}, b);
payload.instance = String(b.instance || '');
payload.telefono = String(b.telefono || '').replace(/[^0-9]/g, '');

return [{ json: { payload: JSON.stringify(payload) } }];
